            crate::outer::who()
        }
    }

    pub struct Pair {
        pub a: i32,
        b: i32,
    }

    impl Pair {
        pub fn new(a: i32) -> Pair {
            Pair { a, b: a * 2 }
        }
        pub fn b(&self) -> i32 {
            self.b
        }
    }
}

